export const AUDIO_WIRING_EXTENSION_KEY = Symbol.for("jshack:display:audioWiring");

const PRIORITY_OPTIONS = Object.freeze({ priority: 1 });
const DOOR_OPTIONS = Object.freeze({ priority: 1, volume: 1.25 });

function atPosition(payload) {
  return payload?.at || null;
}

function xyPosition(payload) {
  const x = Number(payload?.x ?? payload?.at?.x);
  const y = Number(payload?.y ?? payload?.at?.y);
  return Number.isFinite(x) && Number.isFinite(y) ? { x, y } : null;
}

function targetPosition({ targetId }, ctx) {
  return targetId != null ? ctx.getPosition?.(targetId) || null : null;
}

function entityPosition({ entityId }, ctx) {
  return entityId != null ? ctx.getPosition?.(entityId) || null : null;
}

function targetOrOriginPosition(payload, ctx) {
  return payload?.origin || targetPosition(payload, ctx);
}

function targetOrAtPosition(payload, ctx) {
  return payload?.at || targetPosition(payload, ctx);
}

export function resolveAudioPlayKey(payload) {
  return String(payload?.key || payload?.id || payload?.sound || "");
}

