function routeMatchesEvent(route, event) {
  if (Array.isArray(route.event)) return route.event.includes(event);
  return route.event === event;
}

function routeEvents(routes) {
  const events = new Set();
  for (const route of routes || []) {
    if (Array.isArray(route.event)) {
      for (const event of route.event) events.add(event);
    } else if (route.event) {
      events.add(route.event);
    }
  }
  return Array.from(events);
}

export function createAudioWiringExtension(deps) {
  const ctx = {
    getPosition: typeof deps?.getPosition === "function" ? deps.getPosition : () => null,
    getPlayerPosition: typeof deps?.getPlayerPosition === "function" ? deps.getPlayerPosition : () => null,
    getZoomGain: typeof deps?.getZoomGain === "function" ? deps.getZoomGain : () => 1,
    play: typeof deps?.play === "function" ? deps.play : null,
    playAt: typeof deps?.playAt === "function" ? deps.playAt : null,
  };

  return defineExtension("jshack:display:audioWiring", (world) => {
    const unsubs = routeEvents(AUDIO_EVENT_ROUTES).map((event) =>
      world.on(event, (payload) => {
        const plan = resolveAudioRoutePlan(AUDIO_EVENT_ROUTES, event, payload, ctx);
        if (!plan) return;
        if (plan.direct) {
